// Supabase returns one n8n item per row — collect them into one array
// and compute the per-row verification rate (fraction of tracked fields that
// actually have a citation) so the frontend doesn't have to redo that math
// per row itself.
const rows = $input.all().map((item) => item.json);

const extractions = rows.map((row) => {
  const terms = Array.isArray(row.key_terms) ? row.key_terms : [];
  const verifiedCount = terms.filter(
    (t) => typeof t.source_quote === 'string' && t.source_quote.trim().length > 0
  ).length;
  return {
    id: row.id,
    created_at: row.created_at,
    file_name: row.file_name,
    contract_type: row.contract_type,
    needs_human_review: row.needs_human_review ?? false,
    self_consistency_runs: row.self_consistency_runs ?? null,
    field_count: terms.length,
    verified_count: verifiedCount,
    verification_rate: terms.length ? verifiedCount / terms.length : null,
    extraction_cost_usd: row.extraction_cost_usd ?? null
  };
});

return [{ json: { extractions } }];

return [{
  json: {
    extractions: [],
    error: 'Could not load extraction history from the database after 2 attempts.'
  }
}];
